#!/usr/bin/env python3
"""Procedural audio, license 'own' (generated by this script): whoosh.wav, hit.wav, music bed.
Usage: audio_assets.py OUT_DIR SECONDS [tech|calm|uplift]
A basic bed so the video is never silent; swap in a licensed track (spec music.file) for premium work.
"""
import os
import sys

import numpy as np
import soundfile as sf

SR = 44100
rng = np.random.default_rng(7)
STYLES = {
    "tech": dict(bpm=104, chords=[[57, 60, 64], [53, 57, 60], [60, 64, 67], [55, 59, 62]], kick=True),
    "calm": dict(bpm=80, chords=[[60, 64, 67], [57, 60, 64], [53, 57, 60], [55, 59, 62]], kick=False),
    "uplift": dict(bpm=112, chords=[[55, 59, 62], [52, 55, 59], [48, 52, 55], [50, 54, 57]], kick=True),
}


def _norm(x, peak):
    return x / (np.max(np.abs(x)) or 1) * peak


def mtof(m):
    return 440 * 2 ** ((m - 69) / 12)


def whoosh(path):
    n = int(0.75 * SR)
    t = np.arange(n) / SR
    noise = rng.standard_normal(n)
    a = np.interp(t, [0, 0.30, 0.75], [0.015, 0.35, 0.05])  # lowpass opens then closes
    y, prev = np.zeros(n), 0.0
    for i in range(n):
        prev += a[i] * (noise[i] - prev)
        y[i] = prev
    sf.write(path, _norm(y * np.sin(np.pi * np.clip(t / 0.75, 0, 1)) ** 2, 0.7), SR)


def hit(path):
    n = int(0.6 * SR)
    t = np.arange(n) / SR
    f = 40 + 110 * np.exp(-t * 14)
    y = np.sin(2 * np.pi * np.cumsum(f) / SR) * np.exp(-t * 7) + 0.25 * rng.standard_normal(n) * np.exp(-t * 60)
    sf.write(path, _norm(y, 0.8), SR)


def music(path, seconds, style="tech"):
    st = STYLES[style]
    beat = 60 / st["bpm"]
    N = int(seconds * SR)
    out = np.zeros(N + SR * 3)

    def add(sig, start):
        i = int(start * SR)
        if i < len(out):
            j = min(len(out), i + len(sig))
            out[i:j] += sig[: j - i]

    for bar in range(int(np.ceil(seconds / (beat * 4)))):
        ch, t0 = st["chords"][bar % 4], bar * beat * 4
        t = np.arange(int((beat * 4 + 0.8) * SR)) / SR
        env = np.minimum(t / 0.5, 1) * np.where(t < beat * 4, 1, np.exp(-(t - beat * 4) * 6))
        pad = sum(np.sin(2 * np.pi * mtof(m) * t) + 0.4 * np.sin(2 * np.pi * mtof(m) * 2.003 * t)
                  + 0.15 * np.sin(2 * np.pi * mtof(m) * 3 * t) for m in ch)
        add(pad * env * 0.07, t0)
        for k in (0, 2):
            tb = np.arange(int(beat * 2 * SR)) / SR
            add(np.sin(2 * np.pi * mtof(ch[0] - 12) * tb) * np.exp(-tb * 1.8) * 0.35, t0 + k * beat)
        notes = [ch[0], ch[1], ch[2], ch[1]]
        for k in range(8):
            ta = np.arange(int(0.4 * SR)) / SR
            f = mtof(notes[k % 4] + 12)
            add((np.sin(2 * np.pi * f * ta) + 0.3 * np.sin(2 * np.pi * f * 2 * ta)) * np.exp(-ta * 9) * 0.12, t0 + k * beat / 2)
        for k in range(4):
            if st["kick"]:
                tk = np.arange(int(0.3 * SR)) / SR
                add(np.sin(2 * np.pi * np.cumsum(45 + 90 * np.exp(-tk * 30)) / SR) * np.exp(-tk * 10) * 0.5, t0 + k * beat)
            th = np.arange(int(0.06 * SR)) / SR
            add(np.diff(rng.standard_normal(len(th) + 1)) * np.exp(-th * 70) * 0.10, t0 + k * beat + beat / 2)
    y = _norm(out[:N], 0.8)
    a, b = int(1.0 * SR), int(2.0 * SR)
    y[:a] *= np.linspace(0, 1, a)
    y[-b:] *= np.linspace(1, 0, b)
    sf.write(path, y, SR)


def build(out_dir, seconds, style="tech", with_music=True):
    sfx, mus = os.path.join(out_dir, "sfx"), os.path.join(out_dir, "music")
    os.makedirs(sfx, exist_ok=True)
    whoosh(os.path.join(sfx, "whoosh.wav"))
    hit(os.path.join(sfx, "hit.wav"))
    if with_music:
        os.makedirs(mus, exist_ok=True)
        music(os.path.join(mus, "bed.wav"), seconds, style)


if __name__ == "__main__":
    if len(sys.argv) < 3:
        sys.exit(__doc__)
    build(sys.argv[1], float(sys.argv[2]), sys.argv[3] if len(sys.argv) > 3 else "tech")
